size_t fn_13(const unsigned char *in, size_t inlen, uint64_t seed, unsigned char *out, size_t outlen)
{
    unsigned char S[256], *sp;
    uint64_t j;
    size_t i;
    uint8_t k;

    if (outlen < inlen)
        return -1;

    sp = S;
    for (i = 0; i < 256; i++)
        *sp++ = i;

    sp = S;
    for (i = 0; i < 256; i++) {
        j = (j + sp[i] + ((uint8_t)(seed >> (8 * (i & 7))))) & 0xff;
        k = sp[i];
        sp[i] = sp[j];
        sp[j] = k;
    }

    j = i = k = 0;
    for (i = 0; i < inlen; i++) {
        j = (j + S[i]) & 0xff;
        k = (k + S[j]) & 0xff;
        S[j] = S[k];
        S[k] = S[i];
        out[i] = S[(S[i] + S[j]) & 0xff] ^ in[i];
    }

    return inlen;
}
